INSERT INTO `biz_article` (`category_type`, `title`, `summary`, `cover_img`, `content`, `author`, `is_top`, `view_count`, `seo_title`, `seo_keywords`, `seo_description`, `status`, `publish_time`, `create_time`) VALUES 
('news', '热烈庆祝星曜智能科技有限公司正式挂牌成立', '标志着昆明人工智能产业迈出重要一步，市领导莅临指导工作。', '', '<p>正文内容...</p>', '行政部', '1', 2301, '星曜AI成立,昆明人工智能', '星曜,开业,挂牌', '云南星曜人工智能正式成立', '0', NOW(), NOW()),
('news', '星曜AI发布"天眼"3.0算法，识别准确率突破99.9%', '在复杂光线环境下的识别能力大幅提升，误报率降低80%。', '', '<p>技术细节...</p>', '研发中心', '1', 1560, 'AI算法升级,视觉识别', '算法,CV,深度学习', '最新一代算法发布', '0', NOW(), NOW()),
('notice', '关于2026年春节放假安排的通知', '根据国家法定节假日规定，结合公司实际情况，现将春节放假安排如下...', '', '<p>放假安排...</p>', '人事部', '1', 4500, '', '', '', '0', NOW(), NOW()),
('news', '星曜科技中标昆明市高新区智慧社区改造项目', '项目金额达500万元，将为10个老旧小区提供智能化改造服务。', '', '<p>中标详情...</p>', '市场部', '0', 890, '', '', '', '0', NOW(), NOW()),
('culture', '第一届"星曜杯"编程马拉松大赛圆满落幕', '30多位开发者齐聚一堂，用代码改变世界。', '', '<p>活动回顾...</p>', '运营部', '0', 670, '', '', '', '0', NOW(), NOW()),
('news', '行业深度：2025年人工智能在农业领域的应用前景', 'AI如何助力云南高原特色农业？本文深度解析智慧农业的发展趋势。', '', '<p>深度好文...</p>', '星曜研究院', '0', 3400, '智慧农业,AI农业', '农业,乡村振兴', 'AI在农业的应用', '0', NOW(), NOW()),
('notice', '关于公司内部系统升级维护的公告', 'ERP系统将于本周六凌晨进行升级，届时将暂停服务。', '', '<p>升级通知...</p>', 'IT部', '0', 210, '', '', '', '0', NOW(), NOW()),
('news', '星曜AI与云南大学达成产学研战略合作', '双方将共建人工智能联合实验室，培养高素质AI人才。', '', '<p>合作签约...</p>', '总经办', '0', 1120, '', '', '', '0', NOW(), NOW()),
('news', '赋能实体经济：星曜AI助力本地烟草企业实现质检自动化', '通过机器视觉替代人工质检，效率提升300%。', '', '<p>案例分享...</p>', '大客户部', '0', 980, '', '', '', '0', NOW(), NOW()),
('culture', '员工风采：记星曜科技2025年度优秀员工颁奖典礼', '他们是星曜最闪亮的星，来看看他们的奋斗故事。', '', '<p>颁奖现场...</p>', '人事部', '0', 560, '', '', '', '0', NOW(), NOW()),
('notice', '关于规范公司考勤管理的通知', '为了提高工作效率，现对考勤制度进行如下调整...', '', '<p>考勤制度...</p>', '人事部', '0', 3300, '', '', '', '0', NOW(), NOW()),
('news', '喜讯！星曜科技荣获"国家高新技术企业"认定', '这是对公司技术创新能力和核心自主知识产权的充分肯定。', '', '<p>高企认定...</p>', '行政部', '0', 1500, '', '', '', '0', NOW(), NOW()),
('news', '2025世界人工智能大会见闻：星曜AI惊艳亮相', '多款核心产品在大会上展出，吸引了众多国内外客户的关注。', '', '<p>参展回顾...</p>', '品牌部', '0', 880, '', '', '', '0', NOW(), NOW()),
('culture', '星曜科技团建活动：滇池徒步之旅', '快乐工作，认真生活，我们在滇池畔留下了欢声笑语。', '', '<p>照片墙...</p>', '行政部', '0', 450, '', '', '', '0', NOW(), NOW()),
('notice', '关于开展全员网络安全意识培训的通知', '为了保障公司数据安全，定于下周五下午举行安全培训。', '', '<p>培训安排...</p>', 'IT部', '0', 280, '', '', '', '0', NOW(), NOW());
INSERT INTO `biz_product` (`product_name`, `category_id`, `sub_title`, `main_img`, `summary`, `pain_points`, `solutions`, `tech_specs`, `related_ids`, `sort_order`, `status`, `create_time`) VALUES 
('星曜AI边缘计算盒子X1', 1, '小巧强悍，即插即用', 'https://via.placeholder.com/300x200', '专为工业现场设计的边缘计算终端，内置多种识别算法，支持4路摄像头接入。', '传统监控被动；云端带宽贵；断网失效', '<p>边缘计算方案...</p>', '<p>算力: 4TOPS</p>', '', 1, '0', NOW()),
('智慧工地安全监管平台', 2, '安全生产，AI守护', 'https://via.placeholder.com/300x200', '通过视觉AI自动识别未戴安全帽、反光衣、火焰烟雾等危险行为，实时联动广播报警。', '监管难；事故多；取证难', '<p>全域感知方案...</p>', '<p>识别率>99%</p>', '1', 2, '0', NOW()),
('人脸识别门禁考勤一体机', 1, '毫秒级响应，无感通行', 'https://via.placeholder.com/300x200', '支持高达5万人底库，识别速度小于0.3秒，完美适配复杂光线环境。', '排队拥堵；代打卡；指纹不卫生', '<p>通行方案...</p>', '<p>活体检测: 支持</p>', '', 3, '0', NOW()),
('烟火检测智能预警系统', 2, '防患于未燃', 'https://via.placeholder.com/300x200', '利用深度学习算法，实时检测视频画面中的烟雾和火焰，比传统烟感更快发现火情。', '森林防火难；仓库死角多', '<p>视觉消防方案...</p>', '<p>最小像素: 20x20</p>', '1', 4, '0', NOW()),
('车辆特征识别SDK', 3, '不仅仅是车牌识别', 'https://via.placeholder.com/300x200', '可识别车牌、车型、车身颜色、驾驶员是否系安全带、打电话等多种特征。', '车辆管理粗放；违规行为难抓拍', '<p>智慧交通方案...</p>', '<p>支持语言: Java/C++</p>', '', 5, '0', NOW()),
('智慧社区综合管控平台', 2, '打造有温度的社区', 'https://via.placeholder.com/300x200', '集成人脸门禁、车辆道闸、访客系统、视频监控于一体的综合管理平台。', '系统孤岛；数据不通；体验差', '<p>社区大脑...</p>', '<p>B/S架构</p>', '3,5', 6, '0', NOW()),
('工业缺陷检测AOI系统', 1, '机器之眼，精准质检', 'https://via.placeholder.com/300x200', '针对烟草、食品、电子制造行业，自动检测产品表面的划痕、污点、破损。', '人工眼疲劳；漏检率高；招工难', '<p>工业视觉...</p>', '<p>精度: 0.01mm</p>', '', 7, '0', NOW()),
('政务大厅智能导办机器人', 1, '您的贴心办事助手', 'https://via.placeholder.com/300x200', '通过NLP自然语言处理，为市民提供业务咨询、路径指引、排队叫号服务。', '咨询量大；人员不足；重复回答', '<p>智能服务...</p>', '<p>语音交互</p>', '', 8, '0', NOW());
