INSERT INTO `biz_solution` VALUES (1, '智慧城市全域治理方案', '让城市像生命体一样思考与呼吸', '基于城市大脑中台，融合计算机视觉与大数据分析，实现城市交通、安防、管理的全面智能化升级。', 'el-icon-office-building', 'https://images.unsplash.com/photo-1480714378408-67cf0d13bc1b?q=80&w=2070&auto=format&fit=crop', '<p>这里是富文本内容：通过部署边缘计算盒子，实现交通路口的毫秒级响应...</p>', '交通拥堵难以缓解;安防监控存在死角;应急响应速度慢', '全域感知;实时决策;降本增效', '1,3', '0', 1, 'admin', SYSDATE(), '', null, '');
INSERT INTO `biz_solution` VALUES (2, '工业AI视觉质检方案', '比人眼更精准，比机器更智能', '针对制造业流水线，利用深度学习算法检测产品外观缺陷，替代传统人工目检，良品率提升至99.9%。', 'el-icon-monitor', 'https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?q=80&w=2070&auto=format&fit=crop', '<p>这里是富文本内容：支持金属表面划痕检测、PCB电路板缺陷检测...</p>', '人工质检效率低;微小瑕疵难发现;长期作业易疲劳', '7*24小时作业;毫秒级识别;数据可追溯', '2,4', '0', 2, 'admin', SYSDATE(), '', null, '');
INSERT INTO `biz_solution` VALUES (3, '智慧园区通行管理方案', '无感通行，安全随行', '集成人脸识别门禁与访客系统，打造安全、便捷、高效的现代化智慧园区生态。', 'el-icon-place', 'https://images.unsplash.com/photo-1577962917302-cd874c4e31d2?q=80&w=2070&auto=format&fit=crop', '<p>这里是富文本内容：员工刷脸考勤，访客二维码通行...</p>', '外来人员管理乱;高峰期通行拥堵;传统门禁易破解', '刷脸秒过;轨迹追踪;云端管理', '5', '0', 3, 'admin', SYSDATE(), '', null, '');